mapper.select:
SELECT `id`, `F_type`, `E_Level`, `F_Elements`, `Is_Del`, `diseaseid`, `oneself`, `status`, `fs_describe`, `User_code`, `creationTime` FROM `yh_food_srecipe`
Is_Del=2
AND oneself=1
AND user_code=#{usercode} AND oneself=3
AND oneself=3 AND user_code!=#{usercode}
AND f_type=#{ftype}
AND e_level=#{elevel}
AND CONCAT(";",diseaseid,";") LIKE CONCAT('%;',#{diseaseid},'%;')
AND fs_describe LIKE CONCAT('%',#{fsDescribe},'%')
order by STR_TO_DATE(creationTime, '%Y-%m-%d') DESC

SELECT a.`id`, a.`F_type`, a.`E_Level`, a.`F_Elements`, a.`Is_Del`, a.`diseaseid`, a.`oneself`, a.`status`, a.`fs_describe`, a.`User_code`, a.`creationTime`, b.disease_name AS diseaseName
FROM `yh_food_srecipe` AS a LEFT JOIN `yh_disease_category` AS b ON a.diseaseid=b.disease_code
AND a.F_type=#{ftype}
AND a.E_Level=#{eLevel}
AND a.diseaseid=#{diseaseid}

select pe.F_Elements,pe.Fs_Id,pe.D_Type,pe.genter,ca.disease_name,pe.oneself,pe.E_Level from yh_food_srecipe2 pe,yh_disease_category ca

pe.diseaseid=ca.id

	AND
	(
		ca.disease_name like CONCAT('%',#{name},'%' )
	)


	AND
	pe.genter=#{sex}


	AND
	pe.D_Type=#{taste}

SELECT * FROM `yh_food_srecipe2`


and D_Type=#{type}


AND genter=#{sex}


AND Package_number=#{number}


AND diseaseid=#{diseaseid} 


	   limit 1

SELECT * FROM `yh_food_srecipe2`


and D_Type=#{type}


AND genter=#{sex}


AND Package_number=#{number}


AND diseaseid=#{diseaseid} 


AND is_Use=#{isUse} 


	   limit 1

 select * from yh_food_srecipe pe,yh_disease_category ca
		where pe.diseaseid=ca.id
  and pe.id = #{fsId,jdbcType=INTEGER}
